A real multi-cloud apply has a main.tf , a hardened backend.tf , a Vault-driven vault.tf , and a vxcli wrapper that ties it together with policy and audit. Tabs below show all four — pulled from real production templates.
- OPA / Sentinel policies enforced before plan reaches apply
- State diffs rendered in PR comments — readable, not raw HCL
- Drift detection on a schedule per workspace, paged on regression
- Pipeline export to GitHub Actions, GitLab, Jenkins — same plan
```
# Multi-provider Terraform — same workflow, every cloud.
terraform {
  required_version = ">= 1.7"
  required_providers {
    aws        = { source = "hashicorp/aws",        version = "~> 5.0"  }
    azurerm    = { source = "hashicorp/azurerm",    version = "~> 3.0"  }
    google     = { source = "hashicorp/google",     version = "~> 5.0"  }
    kubernetes = { source = "hashicorp/kubernetes", version = "~> 2.0"  }
    vault      = { source = "hashicorp/vault",      version = "~> 4.0"  }
    vxcloud    = { source = "prodxcloud/vxcloud",   version = "~> 1.0"  }
  }
}

# Pull AWS creds dynamically from Vault (1h lease, auto-revoked).
data "vault_aws_access_credentials" "deploy" {
  backend = "aws"
  role    = "tf-deploy"
  type    = "iam_user"
}

provider "aws" {
  region     = "us-east-1"
  access_key = data.vault_aws_access_credentials.deploy.access_key
  secret_key = data.vault_aws_access_credentials.deploy.secret_key
}

# A real workload across two clouds.
module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.5"
  name    = "studio-prod-vpc"
  cidr    = "10.0.0.0/16"
}

resource "vxcloud_vm" "api" {
  name   = "studio-api"
  cloud  = "aws"
  region = "us-east-1"
  type   = "g3.medium"
  count  = 3
  vpc_id = module.vpc.vpc_id
}
```
Generate Terraform from a goal
vxcli terraform new "EKS cluster + RDS Postgres in 2 AZs" — emits main.tf, backend.tf, vault.tf wired to your defaults.
