try {
  await c.deploy.container({ /* … */ });
} catch (err) {
  if (err instanceof VxAuthError)        { /* re-run vxcli auth login */ }
  else if (err instanceof VxValidationError) throw err;
  else if (isRetryable(err))             { /* back off + retry */ }
  else                                    throw err;
}

