for (const row of preview.rows) console.log(row);

// Upload a new dataset (JSONL of { prompt, completion } rows)
const file = readFileSync('./conversations.jsonl');
const ds = await c.agentcontrol.datasets.upload({
  name:     'support-conversations',
  file,
  filename: 'conversations.jsonl',
});
console.log('uploaded:', ds.id, '·', ds.rowCount, 'rows');
```
