await c.leads.getLead(leadId);          // + the live pool row + drift
await c.leads.updateLead(leadId, { status: 'qualified', notes: 'wants a demo' });
await c.leads.convertLead(leadId);
await c.leads.bulkConvertLeads(leadIds);

await c.leads.saveSearch({
  name: 'AU founders, 51-200',
  filters: { countries: ['AU'], seniorities: ['founder'] },
});
await c.leads.listSavedSearches();

// Crawls the company's own site; anything it finds is unverified.
