Go 1.22+ v0.20260817.0 · 19 modules
Idiomatic Go client. One *http.Client per Client, retry/backoff, single-flight refresh on 401, full interface coverage for all platform endpoints.
Install:
```
go get github.com/prodxcloud/vxcloud@latest
```
Quickstart:
```
package main

import (
    "context"
    "fmt"
    vxsdk "github.com/prodxcloud/vxcloud"
)

import (
    "github.com/prodxcloud/vxcloud/deploy"
    "github.com/prodxcloud/vxcloud/install"
)

func main() {
    ctx := context.Background()
    c, err := vxsdk.LoadFromVxcli(ctx) // or vxsdk.New(ctx, vxsdk.WithAPIKey(...))
    if err != nil { panic(err) }

    pipelines, _ := c.CICD().Pipelines().List(ctx)
    for _, p := range pipelines {
        fmt.Println(p.ID, p.Name)
    }

    // Single-call HTTPS deploy: container + nginx + Let's Encrypt cert.
    // Requires grafana.example.com A record -> 13.216.243.13 already set.
    sess, _ := c.Deploy().Container(ctx, deploy.ContainerOpts{
        SSH: install.SSH{
            Host: "13.216.243.13", User: "ubuntu",
            KeyPairName: "AWSPRODKEY1",     // must be in Vault
        },
        Name:      "grafana",
        Image:     "grafana/grafana:latest",
        Ports:     []string{"3000:3000"},
        EnableSSL: true,
        Domain:    "grafana.example.com",
        SSLEmail:  "[email protected]",
    })
    fmt.Println(sess.SessionID, sess.AccessURL)
}
```

