Full session CRUD on the active node — list, inspect, replay (apply), fetch artifacts (pull), tear down.
```
import "github.com/prodxcloud/vxcloud/sessions"

// List recent sessions
list, err := c.Sessions().List(ctx)
if err != nil { panic(err) }
for _, s := range list { fmt.Println(s.ID, s.Status) }

// Inspect one
detail, _ := c.Sessions().Show(ctx, "adc2d5c4-…")
fmt.Println(detail["status"])

// Replay a planned deploy (previous run had --dry-run)
c.Sessions().Apply(ctx, sessions.ApplyInput{SessionID: "adc2d5c4-…"})

// Fetch terraform state + artifacts
artifacts, _ := c.Sessions().Pull(ctx, sessions.PullInput{SessionID: "adc2d5c4-…"})

// Simple tear down (no force)
c.Sessions().Delete(ctx, "adc2d5c4-…")

// Force-delete variant (skips dependency checks server-side)
c.Sessions().DeleteWith(ctx, sessions.DeleteInput{
    SessionID: "adc2d5c4-…",
    Force:     true,
})
```

