Typed error tree — type-assert with `errors.As` to discriminate failure modes.:
```
import (
    "errors"
    vxerrors "github.com/prodxcloud/vxcloud/errors"
)

if _, err := c.Deploy().Container(ctx, /* … */); err != nil {
    var aerr *vxerrors.AuthError
    var verr *vxerrors.ValidationError
    switch {
    case errors.As(err, &aerr):
        // re-run vxcli auth login
    case errors.As(err, &verr):
        // bad input — fix the call
    case vxerrors.IsRetryable(err):
        // back off + retry (network / rate-limit / 5xx)
    default:
        return err
    }
}
```

