// and is the only supported route into a send path.
saved, _ := ss.SaveLeads(ctx, poolIDs)               // snapshot; free
_ = saved

rep, _ := ss.ConvertFromPool(ctx, salesshift.ConvertFromPoolInput{
    PoolPersonIDs:  poolIDs,
    RevealIfNeeded: true,                            // this SPENDS quota
})

// Describe prints every bucket, including the zeros. The buckets sum to
// the number of ids passed, so printing only Converted would turn a
// partial spend into an apparent success.
fmt.Println(rep.Describe())

// Saved-lead side of the same thing:
one, _ := ss.ConvertLead(ctx, leadID, salesshift.ConvertLeadInput{})
many, _ := ss.BulkConvertLeads(ctx, leadIDs)
_, _ = one, many

