```
provider "VxCloud" {
  api_key   = var.VxCloud_api_key
  workspace = var.workspace_id
}

resource "VxCloud_aws_credentials" "main" {
  access_key_id     = var.aws_access_key_id
  secret_access_key = var.aws_secret_access_key
  region            = "us-east-1"
}

